Arguments:
$repositoryRoot = 'F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$reportRoot = Join-Path $repositoryRoot 'artifacts/ecs-relations/measurements/controlled-reads-r30'
function Percentile([object[]]$values, [double]$fraction) {
    $sorted = @($values | Sort-Object)
    $position = ($sorted.Count - 1) * $fraction
    $lower = [int][Math]::Floor($position)
    $upper = [int][Math]::Ceiling($position)
    [double]$sorted[$lower] + ($position - $lower) * ([double]$sorted[$upper] - [double]$sorted[$lower])
}
$submissions = Get-Content -LiteralPath (Join-Path $reportRoot 'submissions.json') -Raw | ConvertFrom-Json
$rows = foreach ($submission in $submissions | Where-Object Comparison -eq 'HandwrittenControl') {
    $report = Get-Content -LiteralPath $submission.Report -Raw | ConvertFrom-Json
    foreach ($side in @('H1','H2')) {
        foreach ($order in @('H1/H2','H2/H1')) {
            $samples = @($report.RawSamples | Where-Object { $_.Boundary -eq $report.Input.PrimaryBoundary -and $_.Side -eq $side -and $_.SideOrder -eq $order })
            $ticks = @($samples.ElapsedTicks)
            $median = Percentile $ticks 0.5
            $p95 = Percentile $ticks 0.95
            [pscustomobject]@{
                CaseId = [string]$submission.CaseId; SourceCommit = $submission.SourceCommit
                Boundary = $report.Input.PrimaryBoundary; Required = $false
                Side = $side; ActualType = if ($side -eq 'H1') { $report.FirstHandwrittenType } else { $report.SecondHandwrittenType }
                SideOrder = $order; Position = if ($order.StartsWith($side + '/')) { 'First' } else { 'Second' }
                Samples = $samples.Count; Frequency = $report.Device.StopwatchFrequency
                MedianTicks = $median; P95Ticks = $p95
                MedianMicroseconds = $median * 1e6 / $report.Device.StopwatchFrequency
                P95Microseconds = $p95 * 1e6 / $report.Device.StopwatchFrequency
            }
        }
    }
}
$destination = Join-Path $repositoryRoot 'docs/evidence/ECS-Relations-2026-10-19/controlled-reads-r30/handwritten-order.json'
@($rows) | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $destination -Encoding utf8
foreach ($row in $rows) {
    Write-Output ('{0} {1} {2} {3}: n={4} medianTicks={5:G17} p95Ticks={6:G17} medianUs={7:G17} p95Us={8:G17}' -f $row.CaseId,$row.Side,$row.SideOrder,$row.Position,$row.Samples,$row.MedianTicks,$row.P95Ticks,$row.MedianMicroseconds,$row.P95Microseconds)
}
Write-Output ('HANDWRITTEN_ORDER ' + $destination)
